/* One direction per slide. Artwork is concept exploration; interface examples are fictional. */
(()=>{
const $=s=>document.querySelector(s), data=window.SHOWCASE;
const all=data.directions, groups=data.groups, slides=['cover',...all.map(d=>d.id),'curation'];
let index=0, filter='all', onlySaved=false, selected=new Set(), saved=new Set(), toastTimer;
try{saved=new Set(JSON.parse(localStorage.getItem('waraqa-shortlist-v1')||'[]').filter(id=>all.some(d=>d.id===id)))}catch{}
const safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=id=>`assets/${id}.webp`;
const get=id=>all.find(d=>d.id===id);
const group=d=>groups.find(g=>g.key===d.group);
const code=d=>d.id.toUpperCase();
const num=n=>String(n).replace(/\d/g,c=>'٠١٢٣٤٥٦٧٨٩'[c]);
const crop=(id,cls='')=>`<div class="crop-hero ${cls}" style="--hero-scale:${10000/(get(id).thumbSplit||65)}%"><img src="${asset(id)}" alt="${safe(get(id).name)}" loading="lazy"></div>`;
const palette=d=>`<div class="palette" aria-label="ألوان مقترحة">${d.palette.map(c=>`<div class="swatch"><i style="background:${c}"></i><span>${c.toUpperCase()}</span></div>`).join('')}</div>`;
const top=(label,id)=>`<div class="slide-top"><span class="collection-mark"><i></i>بوابة الموظفين / ${label}</span><span class="code">${id}</span></div>`;
const bottom=label=>`<div class="slide-bottom"><span>ورقة · استكشاف الشخصية</span><span>${label}</span><span>تصوّرات أولية · أكتوبر ٢٠٢٦</span></div>`;
const demos=[
 {title:'أهلًا بك في الفريق',text:'تعرّف على أقسام البوابة.',action:'اكتشف البوابة',en:'Welcome'},
 {title:'شارك فكرتك',text:'أضف اقتراحك لتطوير العمل.',action:'أضف فكرتك',en:'Ideas'},
 {title:'إجابة صحيحة',text:'يمكنك الانتقال إلى السؤال التالي.',action:'السؤال التالي',en:'Feedback'},
 {title:'فعاليات الفريق',text:'اطّلع على مواعيد الفعاليات القادمة.',action:'عرض الفعاليات',en:'Reminder'}
];
function demo(d){const m=d.demo||demos[(d.index-1)%4];return `<div class="portal-demo"><div class="demo-label">داخل البوابة <span>مثال توضيحي</span></div><div class="portal-content"><div class="portal-copy" lang="ar" dir="rtl"><strong>${m.title}</strong><p>${m.text}</p><span class="demo-action">${m.action}</span></div>${crop(d.id,'mini-mascot')}</div></div>`}
function cover(){return `<section class="slide cover">${top('استكشاف الشخصية','٧٠ اتجاهًا')}<p class="cover-kicker">خامات مختلفة. ملامح جديدة.</p><h1>ورقة<br>بأربعين<br><em>شكلًا.</em></h1><p class="cover-sub">ومعها ثلاثون شخصية جديدة لبوابة الموظفين.</p>${crop('a01','cover-art')}<div class="cover-metrics"><div><b>٤٠</b><span>اتجاهًا لورقة</span></div><div><b>٣٠</b><span>شخصية جديدة</span></div><div><b>٧</b><span>مجموعات</span></div></div><button class="cover-explore" data-go="a01">تصفّح الاتجاهات ←</button>${bottom('الشخصية هي الأساس')}</section>`}
function direction(d){const g=group(d);return `<section class="slide direction" style="--tint:${g.theme}" data-direction="${d.id}">${top(safe(g.label),code(d))}<div class="direction-head"><div><h1>${safe(d.name)}</h1><p class="subtitle">${safe(d.tagline)}</p></div><span class="direction-kind">${['e','f','g'].includes(d.group)?'شخصية جديدة':'ورقة / '+num(String(d.index).padStart(2,'0'))+' من ١٠'}</span></div><img class="sheet" src="${asset(d.id)}" alt="${safe(d.name)}: الشخصية في أربع وضعيات للترحيب والتأكيد والتفكير والتذكير."><div class="art-captions"><span>${['e','f','g'].includes(d.group)?'شخصية جديدة':'تصوّر لشخصية ورقة'}</span><span class="poses">ترحيب · تأكيد · تفكير · تذكير</span></div><aside class="direction-info"><p class="eyebrow">الفكرة</p><p class="persona">${safe(d.persona)}</p><p class="use-line"><b>الاستخدام</b>${safe(d.use)}</p>${palette(d)}<div class="motion-note"><b>حركة<br>مقترحة</b><p>${safe(d.motion)}</p></div>${demo(d)}</aside>${bottom(safe(g.board))}</section>`}
function curation(){const picks=[['a01','الأقرب إلى ورقة','ملامح مألوفة بخامة ناعمة وواضحة.'],['b01','للاستخدام اليومي','شكل واضح وتعابير بسيطة تناسب مواقف متعددة.'],['c07','للواجهة الهادئة','حضور خفيف يترك المساحة للمحتوى.']];return `<section class="slide summary">${top('ترشيحات أولية','الاختيار')}<div class="direction-head"><div><h1>اتجاهات تستحق التطوير</h1><p class="subtitle">ثلاث بدايات مختلفة لشخصية ورقة.</p></div></div><div class="summary-copy"><p class="eyebrow">ترشيحنا</p><h2>ابدأ بالشكل والتعبير.</h2><p>اختر الشخصية الأقرب للبوابة، ثم طوّر خامتها وحركتها.</p><p class="decision">هذه ترشيحات أولية. احفظ ما يعجبك وقارن بينه.</p></div><div class="summary-cards">${picks.map(([id,reason,copy])=>`<button class="pick-card" data-go="${id}">${crop(id)}<small>${reason}</small><h3>${code(get(id))} · ${get(id).name}</h3><p>${copy}</p></button>`).join('')}</div><p class="summary-foot">ومن الشخصيات الجديدة: <b>طيف</b> لشكله المختلف، و<b>نسيج</b> لارتباطه بالتعاون.</p>${bottom('احفظ اتجاهاتك المفضلة وقارن بينها')}</section>`}
function scale(){if(document.body.classList.contains('export-mode'))return;if(innerWidth<=760){$('#stage').style.setProperty('--scale',1);return}const v=$('#viewport');$('#stage').style.setProperty('--scale',Math.min((v.clientWidth-28)/1440,(v.clientHeight-28)/810))}
function updateSaved(){const d=get(slides[index]);$('#savedCount').textContent=saved.size;$('#starButton').hidden=!d;$('#starButton').setAttribute('aria-pressed',d&&saved.has(d.id)?'true':'false');$('#starButton').innerHTML=`${d&&saved.has(d.id)?'★':'☆'} <span>${d&&saved.has(d.id)?'تم الحفظ':'حفظ الاتجاه'}</span>`}
function render(){const id=slides[index],d=get(id);$('#stage').innerHTML=id==='cover'?cover():id==='curation'?curation():direction(d);$('#position').textContent=d?`${num(all.indexOf(d)+1)} من ${num(all.length)}`:id==='cover'?'المجموعة':'الترشيحات';$('#prevButton').disabled=index===0;$('#nextButton').disabled=index===slides.length-1;$('#progressBar').style.width=`${(index+1)/slides.length*100}%`;$('#chapterNav').innerHTML=groups.map(g=>`<button data-go="${g.key}01" class="${d&&d.group===g.key?'active':''}" ${d&&d.group===g.key?'aria-current="true"':''}>${g.label}</button>`).join('');updateSaved();scale();$('#viewport').scrollTop=0;const next=slides[index+1];if(get(next)){const pre=new Image();pre.src=asset(next)}document.title=d?`${code(d)} · ${d.name} — ورقة`:'ورقة — استكشاف الشخصية'}
function go(id){clearTimeout(toastTimer);$("#toast").classList.remove("show");const n=slides.indexOf(id);if(n<0)return;index=n;if(location.hash!==`#${id}`)history.replaceState(null,'',`#${id}`);render()}
function step(n){go(slides[Math.max(0,Math.min(slides.length-1,index+n))])}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function toggleSaved(id){if(saved.has(id))saved.delete(id);else saved.add(id);try{localStorage.setItem('waraqa-shortlist-v1',JSON.stringify([...saved]))}catch{toast('ستبقى المفضلة محفوظة خلال هذه الزيارة.')}updateSaved();if($('#catalog').open)renderGallery()}
function openCatalog(shortlist=false){onlySaved=shortlist;filter='all';$('#search').value='';$('#catalogTitle').textContent=shortlist?'المفضلة':'كل الاتجاهات';renderGallery();$('#catalog').showModal()}
function renderGallery(){const q=$('#search').value.trim().toLowerCase();const matches=all.filter(d=>(!onlySaved||saved.has(d.id))&&(filter==='all'||d.group===filter)&&[d.id,d.name,d.persona,d.use,group(d).label].join(' ').toLowerCase().includes(q));$('#filters').innerHTML=[['all','الكل'],...groups.map(g=>[g.key,g.label])].map(([k,l])=>`<button data-filter="${k}" class="${filter===k?'active':''}" aria-pressed="${filter===k}">${l}</button>`).join('');$('#gallery').innerHTML=matches.map(d=>`<article class="gallery-card"><button class="compare-select" data-compare="${d.id}" aria-pressed="${selected.has(d.id)}" aria-label="${selected.has(d.id)?'إلغاء اختيار':'اختيار'} ${safe(d.name)} للمقارنة">${selected.has(d.id)?'✓':'+'}</button><button class="card-star" data-save="${d.id}" aria-label="${saved.has(d.id)?'إلغاء حفظ':'حفظ'} ${safe(d.name)}">${saved.has(d.id)?'★':'☆'}</button><button class="gallery-open" data-go="${d.id}">${crop(d.id)}<div class="card-meta"><small>${code(d)} / ${safe(group(d).label)}</small><h3>${safe(d.name)}</h3><p>${safe(d.tagline)}</p></div></button></article>`).join('')||(onlySaved?'<div class="empty"><h3>لم تحفظ أي اتجاه بعد.</h3><p>اضغط النجمة بجانب الاتجاه الذي يعجبك.</p></div>':'<div class="empty"><h3>لا توجد نتائج.</h3><p>جرّب كلمة أخرى.</p></div>');$('#galleryCount').textContent=`${matches.length} اتجاه · اختر اتجاهين أو ثلاثة للمقارنة`;$('#compareCount').textContent=selected.size;$('#compareButton').disabled=selected.size<2}
function compare(){if(selected.size<2)return;$('#compareGrid').style.setProperty('--cols',selected.size);$('#compareGrid').innerHTML=[...selected].map(id=>{const d=get(id);return `<article class="compare-column">${crop(id)}<p class="eyebrow">${code(d)} / ${safe(group(d).label)}</p><h3>${safe(d.name)}</h3><p>${safe(d.persona)}</p>${palette(d)}<h4>الاستخدام</h4><p>${safe(d.use)}</p><h4>حركة مقترحة</h4><p>${safe(d.motion)}</p><h4>عند التطوير</h4><p>${safe(d.watch)}</p><button class="compare-open" data-go="${id}">افتح الاتجاه ←</button></article>`}).join('');$('#comparison').showModal()}
document.addEventListener('click',e=>{const goBtn=e.target.closest('[data-go]');if(goBtn){for(const el of document.querySelectorAll('dialog[open]'))el.close();go(goBtn.dataset.go);return}const saveBtn=e.target.closest('[data-save]');if(saveBtn){toggleSaved(saveBtn.dataset.save);return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;renderGallery();return}const c=e.target.closest('[data-compare]');if(c){const id=c.dataset.compare;if(selected.has(id))selected.delete(id);else if(selected.size<3)selected.add(id);else toast('يمكن مقارنة ثلاثة اتجاهات في المرة الواحدة.');renderGallery()}});
$('#nextButton').onclick=()=>step(1);$('#prevButton').onclick=()=>step(-1);$('#overviewButton').onclick=()=>openCatalog();$('#savedButton').onclick=()=>openCatalog(true);$('#starButton').onclick=()=>{const d=get(slides[index]);if(d)toggleSaved(d.id)};$('#closeCatalog').onclick=()=>$('#catalog').close();$('#closeComparison').onclick=()=>$('#comparison').close();$('#compareButton').onclick=compare;$('#search').oninput=renderGallery;
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.body.requestFullscreen();scale()}catch{toast('العرض بملء الشاشة غير متاح في هذا المتصفح.')}}$('#fullscreenButton').onclick=fullscreen;
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea')||document.querySelector('dialog[open]'))return;if(['ArrowLeft','PageDown',' '].includes(e.key)){e.preventDefault();step(1)}else if(['ArrowRight','PageUp'].includes(e.key)){e.preventDefault();step(-1)}else if(e.key==='Home'){e.preventDefault();go('cover')}else if(e.key==='End'){e.preventDefault();go('curation')}else if(e.key.toLowerCase()==='g')openCatalog();else if(e.key.toLowerCase()==='f')fullscreen();else if(e.key.toLowerCase()==='s'){const d=get(slides[index]);if(d)toggleSaved(d.id)}});
let touchStart;$('#viewport').addEventListener('touchstart',e=>{touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});$('#viewport').addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>90&&Math.abs(dx)>Math.abs(dy)*1.8)step(dx<0?1:-1);touchStart=null},{passive:true});
addEventListener('resize',scale);document.addEventListener('fullscreenchange',scale);addEventListener('hashchange',()=>go(location.hash.slice(1)));if(new URLSearchParams(location.search).has('export'))document.body.classList.add('export-mode');
window.waraqa={go,slides,data,render,compare,openCatalog};go(slides.includes(location.hash.slice(1))?location.hash.slice(1):'cover');
})();
